// Map only custom-transition targets; scene and Flux targets are unchanged.
const transitionGroupTargets = {
    "light.helper_living_light_down_chill_all": "light.zigbee_group_living_downlights_chill",
    "light.helper_living_light_down_nonchill_all": "light.zigbee_group_living_downlights_nonchill",
    "light.helper_living_bar_all": "light.zigbee_group_bar_strips_all",
    "light.helper_deck_down_all": "light.zigbee_group_deck_downlights_all",
    "light.helper_deck_strip_all": "light.zigbee_group_deck_strips_all"
};

var inputPayload = msg.payload;
const requestedLight = inputPayload.attributes.light;
const targetLight = typeof requestedLight === "string" &&
    Object.prototype.hasOwnProperty.call(transitionGroupTargets, requestedLight)
    ? transitionGroupTargets[requestedLight]
    : requestedLight;

msg.payload = {
    data: {
        brightness: parseInt(inputPayload.state),
        transition: msg.transition
    },
    target: {
        entity_id: targetLight
    }
};

if (inputPayload.attributes.color_temp) {
    msg.payload.data.color_temp = parseInt(inputPayload.attributes.color_temp);
}

if (inputPayload.attributes.xy_color) {
    msg.payload.data.xy_color = JSON.parse(inputPayload.attributes.xy_color);
}

return msg;

var friendlyName = msg.data.event.new_state.attributes.friendly_name;
var sensorMatch = /(^.+?)\/leak\/(\S+)/.exec(friendlyName);
var message = `${sensorMatch[1]} ${sensorMatch[2]}`;

var title = "Leak detected";
msg.payload = { data: { message, title } };

return msg;

var title = "Low Battery";
var entityName = msg.data.event.new_state.attributes.friendly_name;
var batteryLevel = msg.data.event.new_state.state;
var message = `${entityName} ${batteryLevel}%`;
msg.payload = {
    data: {
        message,
        title
    }
};

return msg;

msg.data = {
  event: {
    entity_id: msg.payload.entity_id,
    new_state: msg.payload
  }
};

return msg;

const brightness_move =
  parseInt(msg.payload.action_rotation_angle_speed, 10);

const response = {
    payload: {
        brightness_move,
        transition: 0
    }
};

return response;

const brightness_move =
  parseInt(msg.payload.action_rotation_angle_speed, 10);

const inverted_brightness_move = 0 - brightness_move;

const response = {
    payload: {
        brightness_move: inverted_brightness_move,
        transition: 0
    }
};

return response;

const blind = msg.blind;
const position = blind?.attributes?.current_position;

if (!blind || blind.state === 'unknown' || blind.state === 'unavailable' ||
    typeof position !== 'number' || !Number.isFinite(position) ||
    position < 0 || position > 100) {
    node.warn('Landing blind position unavailable or invalid; no command sent.');
    return null;
}

msg.blindTargetPosition =
    position === 0
        ? 100
        : position > 45
            ? 45
            : 0;

return msg;

const landingScenes = {
    bright: 'scene.landing_bright',
    chill: 'scene.landing_chill',
    morning: 'scene.landing_morning',
    rainyday: 'scene.landing_rainy_day',
    nightlight: 'scene.landing_nightlight',
    off: 'scene.scene_landing_off'
};

// Desk leaves the Landing scene selector unchanged so a hold restores the room mode.
if (!Object.prototype.hasOwnProperty.call(landingScenes, msg.landingMode)) {
    node.warn('Current scene selector is unavailable or unrecognised; no lights changed.');
    return null;
}

msg.landingScene = landingScenes[msg.landingMode];
return msg;

