// Consume HA policy only. No global HA cache dependency and no retained command queue.
const now = Date.now();
const snapshot = msg.ev_snapshot;
const a = snapshot && snapshot.attributes;
const map = {off:'Stopped',eco_plus:'Eco+',eco:'Eco',fast:'Fast'};
if (!snapshot || snapshot.state !== 'ready' || !a || !map[a.desired] ||
    !Number.isFinite(a.sampled_at) || now-a.sampled_at*1000 < 0 || now-a.sampled_at*1000 > 45000 ||
    typeof a.generation !== 'string' || !a.generation.startsWith('g') ||
    !Number.isFinite(a.policy_changed_at) || now<a.policy_changed_at*1000) {
    node.status({fill:'grey',shape:'ring',text:'waiting for current HA policy'});
    return [null,null];
}
const desired = map[a.desired];
const key = a.generation+'|'+a.desired;
let outstanding=flow.get('ev_mode_outstanding_v2') || {};
let r = flow.get('ev_mode_recovery_v2');
if (!r || r.key !== key) r={key,mode:a.desired,attempts:0,first:now,last:0,next:0,pending:false,token:'',completed:0,alerted:false,offline:false,reassert:Object.values(outstanding).some(x=>x.mode!=='off' && x.key!==key)};
const superseded=Object.values(outstanding).some(x=>x.mode!=='off' && x.key!==key);
const actualValid = a.actual_available === true && Object.values(map).includes(a.actual);
const sourceAge = now-Number(a.reported_at)*1000;
const sourceFresh = actualValid && sourceAge>=0 && sourceAge<=180000;
const match = sourceFresh && a.actual===desired;
let notify = null;
const persist = () => flow.set('ev_mode_recovery_v2',r);
// An optimistic select update is not the end of recovery. A later native report must follow completion.
if (match && !r.reassert && !superseded && (!r.pending || (r.completed>0 && a.reported_at*1000>r.completed+30000))) {
    r={key,mode:a.desired,attempts:0,first:now,last:0,next:0,pending:false,token:'',completed:0,alerted:false,offline:false};
    persist();node.status({fill:'green',shape:'dot',text:'observed '+desired});
    return [null,null];
}
if ((r.attempts>=4 || now-r.first>=300000) && !r.alerted) {
    r.alerted=true;
    notify={payload:{data:{message:(sourceFresh ? 'EV charger has not confirmed '+desired+' ('+(a.reason||'current HA policy')+'). Recovery is continuing with backoff.' : 'EV charger feedback is unavailable or stale for '+desired+'. Active starts remain blocked; Stop recovery continues when required.'),data:{tag:'energy-ev-mode-recovery'}}}};
}
// Stopped is immediate. Existing 20-second qualification remains for every energising mode.
if (desired!=='Stopped' && now-a.policy_changed_at*1000<20000) {
    persist();node.status({fill:'blue',shape:'ring',text:'qualifying '+desired});return [null,notify];
}
if (match && !r.reassert) {
    persist();node.status({fill:'yellow',shape:'ring',text:'awaiting later '+desired+' report'});return [null,notify];
}
if (!sourceFresh && desired!=='Stopped') {
    r.offline=true;persist();node.status({fill:'grey',shape:'ring',text:'waiting for charger feedback'});return [null,notify];
}
if (Object.values(outstanding).some(x=>x.key===key && now-x.issued<120000)) {
    persist();node.status({fill:'yellow',shape:'ring',text:'waiting for current service return'});return [null,notify];
}
if (desired!=='Stopped' && Object.values(outstanding).filter(x=>x.mode!=='off').length>=8) {
    persist();node.status({fill:'red',shape:'ring',text:'too many unresolved requests; active dispatch blocked'});return [null,notify];
}
const reconnected=r.offline && sourceFresh && now-r.last>=15000;
if (now<r.next && !reconnected && !r.reassert) { persist();return [null,notify]; }
r.attempts+=1;
r.last=now;r.completed=0;r.pending=true;r.offline=!sourceFresh;
const waits=desired==='Stopped'?[15000,30000,60000,300000]:[60000,120000,300000];
r.next=now+waits[Math.min(r.attempts-1,waits.length-1)];
r.token=key+'|'+now+'|'+r.attempts;
r.reassert=false;
// Expired Stop promises cannot energise the car; retain every unresolved active token (maximum8).
for (const [token,entry] of Object.entries(outstanding)) if (entry.mode==='off' && now-entry.issued>=120000) delete outstanding[token];
outstanding[r.token]={key,mode:a.desired,issued:now};flow.set('ev_mode_outstanding_v2',outstanding);
persist();
node.status({fill:'yellow',shape:'dot',text:'request '+desired+' #'+r.attempts});
return [{zappi_option:desired,ev_mode:a.desired,ev_generation:a.generation,ev_token:r.token,ev_issued_at:now},notify];

// Service return is not physical confirmation. Late energising work requires reasserting current policy.
const r=flow.get('ev_mode_recovery_v2');
const outstanding=flow.get('ev_mode_outstanding_v2') || {};
const previous=outstanding[msg.ev_token];
if (previous) {delete outstanding[msg.ev_token];flow.set('ev_mode_outstanding_v2',outstanding);}
if (!r) return {ev_reconcile:true};
if (r.token!==msg.ev_token) {
    if (previous && previous.mode!=='off' && previous.key!==r.key) {r.reassert=true;r.pending=true;r.completed=0;flow.set('ev_mode_recovery_v2',r);}
    return {ev_reconcile:true};
}
r.completed=Date.now();
if (msg.error) r.last_error=String(msg.error.message||'service failed').slice(0,160);
else delete r.last_error;
flow.set('ev_mode_recovery_v2',r);
return {ev_reconcile:true};

